    var parts = [];
    if (q && q.value) parts.push('q=' + encodeURIComponent(q.value));
    if (search && search.value) parts.push('search=' + encodeURIComponent(search.value));
    url = '/ui2/history' + (parts.length ? '?' + parts.join('&') : '');
